TP.register({id:"lp1-g4",lp:1,grade:"4",mode:"baseline",nextGrade:"5th grade",build(E){const F=E.F;const FABLE="The summer sun beat down on the empty lot behind Maple Street. Weeds stood as tall as Jada’s little brother, and broken bottles glittered in the dirt. “This is where we’re building the garden?” Leo groaned. “It would take a Herculean effort to clean this up.” Jada pulled on her gloves. “Then we’d better start.” All morning they yanked weeds and hauled trash to the curb. By noon, Leo’s arms felt like wet noodles, and the lot looked almost the same. He dropped his rake. “This is hopeless.” Just then Mrs. Ortiz from next door walked over carrying a shovel. Behind her came Mr. Chen with a wheelbarrow, then the twins from across the street. Word had spread through the neighborhood like wildfire. By sunset, twelve neighbors had cleared the lot down to bare, dark soil. Jada pressed the first tomato seedling into the ground and patted the dirt around it. Leo wiped his forehead and grinned. “Okay,” he said. “Maybe it wasn’t hopeless. It just wasn’t a two-person job.”";const FABLE_N=FABLE.split(/\s+/).length;const TEXT_A={title:"Underground Helpers",body:"Earthworms spend their lives tunneling through the soil. Their tunnels let air and water reach the roots of plants. As they dig, earthworms eat dead leaves and bits of old plants. What comes out the other end is called castings. Castings are full of nutrients that help new plants grow. A garden with many earthworms usually has rich, healthy soil."};const TEXT_B={title:"A Worm’s Body",body:"An earthworm has no eyes, ears, or legs. It moves by squeezing and stretching the muscles along its body. Tiny bristles on its skin grip the dirt so it can push forward. An earthworm breathes through its skin, which must stay damp. If its skin dries out in the sun, the worm cannot breathe. That is one reason earthworms stay underground during the day."};const RAINBOW="Sunlight looks white, but it is really made of many colors. When sunlight enters a raindrop, it bends. Then it bounces off the back of the drop and bends again on the way out. The bending spreads the light into bands of color: red, orange, yellow, green, blue, and violet. You can only see a rainbow when the sun is behind you and the rain is in front of you.";const WORDS=["disappearance","unforgettable","microscope","telephone","reconsider","misbehavior","international","subtraction","uncomfortable","biography","dismortable","replanicate"];function twoTextsHtml(){return`<div class="texts"><article><h3>Text 1: ${TEXT_A.title}</h3><p>${TEXT_A.body}</p></article><article><h3>Text 2: ${TEXT_B.title}</h3><p>${TEXT_B.body}</p></article></div>`}function fracRect(xs,shade){const w=320,h=110;let s=`<svg viewBox="0 0 ${w+8} ${h+8}" width="${w+8}" role="img" aria-label="Rectangle split into ${xs.length-1} parts">`;for(let k=0;k<xs.length-1;k++)s+=`<rect x="${4+xs[k]*w}" y="4" width="${(xs[k+1]-xs[k])*w}" height="${h}" fill="${k<shade?"var(--gold)":"var(--surface)"}" stroke="var(--ink)" stroke-width="4"/>`;return s+"</svg>"}function numLine(parts,dot,letters){const w=560,x0=40,x1=520,y=50;let s=`<svg viewBox="0 0 ${w} 120" width="${w}" role="img" aria-label="Number line from 0 to 1 in ${parts} equal parts"><line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="var(--ink)" stroke-width="4"/>`;for(let k=0;k<=parts;k++){const x=x0+(x1-x0)*k/parts,end=k===0||k===parts;s+=`<line x1="${x}" y1="${y-(end?20:13)}" x2="${x}" y2="${y+(end?20:13)}" stroke="var(--ink)" stroke-width="4"/>`;const lb=k===0?"0":k===parts?"1":letters?"ABCDEFG"[k-1]:"";if(lb)s+=`<text x="${x}" y="${y+52}" font-size="26" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${lb}</text>`}if(dot!=null)s+=`<circle cx="${x0+(x1-x0)*dot/parts}" cy="${y}" r="12" fill="var(--coral)"/>`;return s+"</svg>"}function lab(x,y,t,sz){return`<text x="${x}" y="${y}" font-size="${sz||26}" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${t}</text>`}function shapes4(){return`<svg viewBox="0 0 780 175" width="780" role="img" aria-label="Four shapes labeled A, B, C, and D"><g fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="4" stroke-linejoin="round"><rect x="20" y="30" width="150" height="90"/><polygon points="230,120 230,30 350,120"/><polygon points="420,120 460,30 590,30 550,120"/><polygon points="640,120 700,25 760,120"/></g>${lab(95,160,"A")}${lab(290,160,"B")}${lab(505,160,"C")}${lab(700,160,"D")}</svg>`}function lookBackTexts(){return`<details class="look-back" open><summary>Look back at the two texts</summary>${twoTextsHtml()}</details>`}const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const STOPS=[{id:1,title:"Word Flip",parts:[{std:["RF.4.3"],kind:"words",words:WORDS,n:12,dur:90,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading long words with prefixes, roots, and suffixes",key:["Read each word. dismortable and replanicate are made-up words: listen for the prefix, the middle, and the suffix (dis-mort-a-ble, re-plan-i-cate).","Watch for: prefixes (dis-, un-, re-, mis-, inter-, sub-), roots (micro, scope, tele, phone, bio, graph), suffixes (-ance, -able, -tion, -ior), and whether the student breaks long words into syllables or guesses from the first letters."]}]},{id:2,title:"Read the Story",short:"Read",parts:[{std:["RF.4.4"],kind:"read",n:FABLE_N,label:"words read correctly",dur:120,dir:"Read the story out loud. Use your best reading voice.",desc:`a ${FABLE_N}-word grade-level story read aloud`,html:()=>`<p class="passage">${FABLE}</p>`,key:[`${FABLE_N} words. Time 1 minute and mark errors and self-corrections on your own copy.`,"Fall grade 4 benchmark: about 94 words correct per minute (50th percentile).","Note pace and expression."]}]},{id:3,title:"Story Questions",short:"Story Qs",parts:[{title:"Prove It",std:["RL.4.1"],dur:120,dir:"Answer out loud. Look back at the story for details.",desc:"questions answered with details and examples from a story",html:()=>`<p class="passage sm">${FABLE}</p>`,qs:["How did Leo feel about the job at noon? Give details from the story.","Why did so many neighbors show up? Use a detail from the story.","What changed Leo’s mind by the end? Give an example from the story."],key:["Tired and ready to quit. Details: his arms felt like wet noodles, the lot looked almost the same, he dropped his rake, he said “This is hopeless.” (RL.4.1, explicit)","They heard about the garden and came to help. Detail: “Word had spread through the neighborhood like wildfire.” (RL.4.1, inference)","Twelve neighbors helped and the lot was cleared by sunset. Example: he says it wasn’t hopeless, it just wasn’t a two-person job. (RL.4.1, inference)"]},{title:"Word Meanings",std:["RL.4.4"],dur:75,dir:"Look back at the story. Answer out loud.",desc:"meanings of words and phrases in a story, including one from mythology",qs:["What does “a Herculean effort” mean? Who was Hercules?","What does “Leo’s arms felt like wet noodles” mean?","What does “Word had spread through the neighborhood like wildfire” mean?"],key:["A huge effort that takes great strength. Hercules was a very strong hero in Greek myths. (RL.4.4, allusion to mythology)","His arms were tired and weak. (RL.4.4)","The news traveled very fast from person to person. (RL.4.4)"]}]},{id:4,title:"Two Texts",parts:[{title:"Use the Text",std:["RI.4.1"],n:3,dur:145,dir:"Read both texts to yourself. Then answer out loud.",desc:"questions answered with details from informational texts",html:()=>twoTextsHtml(),qs:["How do earthworms help plants? Give two details from Text 1.","Why would a worm be in danger on a hot, dry sidewalk? Use details from Text 2.","Text 1 says castings are full of nutrients. Use details from Text 1 to explain where castings come from in the first place."],key:["Any two: tunnels let air and water reach roots; they eat dead leaves; castings add nutrients to the soil. (RI.4.1, explicit)","Its skin would dry out, and it breathes through its skin, so it could not breathe. (RI.4.1, inference)","From what the worm eats as it digs: dead leaves and bits of old plants go in, and what comes out the other end is called castings. Or: an answer that names the eating and the coming out without the words dead leaves counts, as long as it is tied to the text. Partial: naming castings as good for soil, which the text already says, without saying where they come from, is approaching. (RI.4.1, explicit)"]},{title:"Put It Together",std:["RI.4.9"],n:3,dur:110,dir:"Think about both texts. Answer out loud.",desc:"putting together information from two texts on the same topic",qs:["Use both texts. Explain how an earthworm’s body helps it do its job in the soil.","Text 2 says an earthworm stays underground during the day so its skin will not dry out. Use Text 1 to explain why that habit is good news for a garden."],key:["Uses Text 2: muscles and bristles let it push and grip to move through dirt. (RI.4.9)","Connects to Text 1: that digging makes tunnels that bring air and water to roots, and its eating makes castings. (RI.4.9)","Staying underground keeps the worm down in the soil, and Text 1 says that is where the good it does happens: the tunnels let air and water reach plant roots, it eats dead leaves, and its castings add nutrients. So the hours the worm spends out of the sun are the hours it spends making the soil rich. Needs the damp-skin reason from Text 2 joined to a soil benefit from Text 1. One text on its own does not answer it. (RI.4.9)"]}]},{id:5,title:"Explorer’s Notebook",short:"Notebook",parts:[{std:["W.4.8"],dur:120,dir:"Look back at the two texts. Write your notes on your paper and hold it up.",desc:"taking notes in their own words, sorting the notes, and listing sources",html:()=>`<p class="big" style="margin-top:0">You are gathering facts for a report about how earthworms live.</p>${lookBackTexts()}`,qs:["Write two notes about earthworms, one from each text. Keep them short and use your own words.","Sort your notes. Write a heading above each note: Helping the Soil or Body Parts.","List your sources. Next to each note, write the title of the text it came from."],key:["Two short notes, one from each text, in the student’s own words and not copied sentences. Examples: worm tunnels bring air and water to roots; worms breathe through damp skin. (W.4.8: gathers information, takes notes, paraphrases)","Each note sits under the heading that fits. Text 1 facts (tunnels, eating dead leaves, castings) go under Helping the Soil. Text 2 facts (no eyes or legs, muscles, bristles, breathing through skin) go under Body Parts. (W.4.8: categorizes)","Writes both titles, each next to the right note: Underground Helpers and A Worm’s Body. (W.4.8: lists sources)"]}]},{id:6,title:"Listen and Retell",short:"Listen",parts:[{std:["SL.4.2"],n:3,label:"checks met",dur:90,dir:"Listen to your teacher read. Then tell it back in your own words.",desc:"retelling a text read aloud in their own words",html:()=>`<p class="huge" aria-hidden="true">${F.icon("rainbow",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about rainbows. Then tell it back in your own words.</p>`,read:RAINBOW,key:["Tells the main idea: raindrops bend sunlight and spread it into colors. (SL.4.2)","Includes 2 or more key details: sunlight is made of many colors; light bends going in, bounces, and bends coming out; the sun must be behind you with rain in front. (SL.4.2)","Uses their own words, not the passage word for word. (SL.4.2)"]}]},{id:7,title:"Grammar Fix",short:"Grammar",parts:[{std:["L.4.1"],dur:75,dir:"Say each sentence out loud the correct way.",desc:"spoken grammar items (relative pronouns, progressive tense, adjective order, fragments, confused words)",qs:["The girl ____ won the race is my cousin. (who or which)","Right now I ____ my bike. (ride)","Fix the order: a red small bag","Fix it so it is a whole sentence: Ran to the store after school.","I want to go ____. (to, too, or two)"],key:["who (L.4.1, relative pronoun)","am riding (L.4.1, progressive tense)","a small red bag (L.4.1, order of adjectives)","Adds a subject, such as: She ran to the store after school. (L.4.1, fixing a fragment)","too (L.4.1, frequently confused words)"]}]},{id:8,title:"Tell Me How",parts:[{std:["SL.4.4"],n:4,label:"checks met",dur:90,dir:"Talk for about one minute. Speak clearly.",desc:"explaining how to do something out loud in an organized way",html:()=>`<p class="big">Tell me about something you know how to do well. Explain it so I could do it too.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">What it is</span><span class="pill" style="font-size:1.4rem">Steps or facts</span><span class="pill" style="font-size:1.4rem">Details</span></div>`,key:["Tells it in an organized order (SL.4.4)","Gives facts that fit the topic (SL.4.4)","Adds relevant, descriptive details that support the main idea (SL.4.4)","Speaks clearly at a pace you can follow (SL.4.4)"]}]},{id:9,title:"Place Value",parts:[{std:["4.NBT.A.1"],dur:75,dir:"Look at the number. Answer out loud.",desc:"place value and how a digit is worth 10 times as much one place to the left",fig:()=>`<p class="huge">7,700</p>`,qs:["In 7,700, how does the 7 in the thousands place compare to the 7 in the hundreds place?","700 ÷ 70 = ?","In 44,400, the 4 in the thousands place is worth 4,000. How many times as much is the 4 in the ten thousands place worth?"],key:["It is 10 times as much (7,000 vs 700). Partial: naming the two values with no comparison is approaching.","10. Partial: 100 counts two places instead of one and does not count.","10 times as much (40,000 is 10 times 4,000). Partial: naming the two values with no comparison is approaching."]}]},{id:10,title:"Round It",parts:[{std:["4.NBT.A.3"],dur:75,dir:"Say each answer out loud.",desc:"rounding multi-digit numbers to a given place",qs:["Round 83,549 to the nearest thousand.","Round 83,549 to the nearest hundred.","Round 83,549 to the nearest ten thousand.","Round 2,961 to the nearest hundred."],key:["84,000. Partial: 83,000 rounds down when the hundreds digit is 5 and does not count.","83,500. Partial: 83,600 rounds up when the tens digit is 4 and does not count.","80,000. Partial: 90,000 rounds up when the thousands digit is 3 and does not count.","3,000. Partial: 2,900 rounds down when the tens digit is 6 and does not count."]}]},{id:11,title:"Times As Many",short:"Times",parts:[{std:["4.OA.A.1"],dur:90,dir:"Say number 1 out loud. Write 2 and 3 on your paper and hold it up.",desc:"multiplication as a comparison (times as many)",qs:["35 = 5 × 7. Finish the sentence: 35 is ____ times as many as 7.","Write an equation for this: 24 is 4 times as many as 6.","Dan has 8 cards. Mia has 3 times as many cards as Dan. Write an equation and solve."],key:["5. The blank is 5 and only 5, because 35 is 5 groups of 7. Do not accept 7 here. (The sentence “35 is 7 times as many as 5” is also true, but it is a different sentence and not an answer to this one.) Partial: 7 answers a different sentence and does not count.","24 = 4 × 6. Or: 4 × 6 = 24 written the other way round counts equally.","3 × 8 = 24. Mia has 24 cards. Partial: the equation right with no answer in cards is approaching."]}]},{id:12,title:"Measure Up",short:"Measure",parts:[{title:"Units",std:["4.MD.A.1"],dur:75,dir:"Answer out loud.",desc:"sizes of measurement units and changing a larger unit to a smaller unit",qs:["How many centimeters are in 3 meters?","How many minutes are in 2 hours?","Which is heavier: 1 kilogram or 900 grams?","4 feet = ____ inches"],key:["300 cm. Or: 3 × 100 = 300. Partial: 30 cm uses tens instead of hundreds and does not count.","120 minutes. Partial: 120 with no unit named is approaching.","1 kilogram (it is 1,000 grams). Partial: naming the kilogram with no change into grams is approaching.","48 inches. Or: 4 × 12 = 48. Partial: 48 with no unit named is approaching."]},{title:"Area and Perimeter",std:["4.MD.A.3"],n:3,dur:90,dir:"Solve on your paper. Show your work and hold it up.",desc:"area and perimeter of rectangles",qs:["A garden is 9 feet long and 6 feet wide. Find the area and the perimeter.","A room has an area of 56 square feet. It is 7 feet wide. How long is it?"],key:["Area: 54 square feet (9 × 6). Partial: 54 with no square unit named is approaching.","Perimeter: 30 feet (9 + 9 + 6 + 6). Or: 2 × 9 + 2 × 6 = 30. Partial: 54 given as the perimeter is the area and does not count.","8 feet (56 ÷ 7). Partial: 8 with no unit named is approaching."]}]},{id:13,title:"Lines and Angles",short:"Shapes",parts:[{std:["4.G.A.2"],dur:75,dir:"Look at the shapes. Answer out loud with the letters.",desc:"sorting shapes by parallel sides, perpendicular sides, and right angles",fig:()=>`<div class="figure">${shapes4()}</div>`,qs:["Which shapes have parallel sides?","Which shapes have perpendicular sides?","Which shape is a right triangle? How do you know?"],key:["A and C. Partial: one of the two shapes named is approaching.","A and B. Partial: one of the two shapes named is approaching.","B. It has one right angle (a square corner). Partial: naming B with no reason is approaching."]}]},{id:14,title:"Fraction Match",short:"Fractions",parts:[{title:"Equal Fractions",std:["4.NF.A.1"],n:3,dur:75,dir:"Look at the two bars. Answer out loud. Write your fractions on your paper.",desc:"explaining and making equivalent fractions",fig:()=>`<div class="figure"><div>${fracRect([0,.5,1],1)}<p class="fig-label">1/2</p></div><div>${fracRect([0,.125,.25,.375,.5,.625,.75,.875,1],4)}<p class="fig-label">4/8</p></div></div>`,qs:["Do these show the same amount? Explain using the number of parts and the size of the parts.","Write two fractions that are equal to 2/3."],key:["Yes, the same amount is shaded. Partial: saying yes with nothing said about the parts is approaching.","Explains: the second bar has 4 times as many parts, and each part is 4 times smaller, so the amount is the same. Partial: naming the number of parts with nothing said about their size is approaching.","Any two: 4/6, 6/9, 8/12, 10/15. Partial: one equal fraction given is approaching."]},{title:"Compare Fractions",std:["4.NF.A.2"],n:3,dur:95,dir:"Show your thinking on your paper and hold it up.",desc:"comparing fractions with different numerators and denominators",qs:["Which is greater: 2/3 or 3/5? Show how you know.","Which is greater: 3/8 or 1/2? Show how you know.","Write &gt;, &lt;, or = between these two: 2/5 ____ 4/10. Show how you know."],key:["2/3. Shows 10/15 and 9/15, or another valid reason. Or: compare both with 1/2, since 2/3 is further above it than 3/5. Partial: naming 2/3 with no reason is approaching.","1/2. 1/2 is 4/8, and 3/8 is less than 4/8 (benchmark). Partial: naming 1/2 with no reason is approaching.","2/5 = 4/10. Shows 2/5 as 4/10, or 4/10 as 2/5, so the two are the same number. Or: a drawing of two same-sized bars with the same amount shaded counts. Partial: naming them equal with no reason shown, or writing &gt; or &lt; because the numbers look different, is approaching. (4.NF.A.2)"]}]},{id:15,title:"Decimals",parts:[{title:"Fractions and Decimals",std:["4.NF.C.6"],dur:60,dir:"Write your answers on your paper and hold it up.",desc:"writing tenths and hundredths as decimals and fractions",fig:()=>`<div class="figure">${numLine(10,4,false)}</div>`,qs:["Write 7/10 as a decimal.","Write 0.62 as a fraction.","What decimal is at the dot on the number line?"],key:["0.7. Or: 7/10 is 70/100, which is 0.70.","62/100. Or: 0.62 is 6 tenths and 2 hundredths, which is 60/100 + 2/100.","0.4. Partial: 4 with no decimal point does not count."]},{title:"Compare Decimals",std:["4.NF.C.7"],n:3,dur:60,dir:"Answer out loud. Tell how you know.",desc:"comparing decimals to hundredths",qs:["Which is greater: 0.5 or 0.45? How do you know?","Use &gt;, &lt;, or =: 0.3 ____ 0.30"],key:["0.5 is greater. Partial: naming 0.5 with no reason is approaching.","Reason: 0.5 is 50 hundredths and 0.45 is 45 hundredths, or uses a model. Partial: naming the hundredths with no comparison made is approaching.","0.3 = 0.30. Partial: making 0.30 the greater one counts digits instead of places and does not count."]}]},{id:16,title:"Write About It",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Tell what you think and why"},std:["W.4.1","L.4.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an opinion writing piece",html:()=>`<p class="big">Should every neighborhood have a community garden? Write your opinion. Write 5 or 6 sentences.</p><ul class="qlist" style="margin-top:14px"><li>State your opinion</li><li>Give reasons with facts or details</li><li>Use linking words: for instance, in addition, in order to</li><li>End with a concluding sentence</li></ul>`,key:["Introduces the topic and states an opinion (W.4.1)","Gives reasons supported by facts and details (W.4.1)","Links opinion and reasons with words like for instance, in order to, in addition (W.4.1)","Ends with a concluding statement (W.4.1)","Complete sentences, no fragments or run-ons (L.4.1)"]},{alt:{group:"write",key:"facts",label:"Facts",icon:"🔎",hint:"Explain how earthworms help a garden"},std:["W.4.2","L.4.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">How do earthworms help a garden? Write to explain it. Use facts from the two texts. Write 5 or 6 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Introduce your topic</li><li>Give facts, details, or examples</li><li>Use linking words: for example, also, because</li><li>End with a concluding sentence</li></ul>${lookBackTexts()}`,key:["Introduces the topic clearly (W.4.2)","Develops the topic with facts, details, or examples from the texts, such as tunnels, air and water for roots, or castings (W.4.2)","Links ideas with words like for example, also, because, another (W.4.2)","Ends with a concluding statement (W.4.2)","Complete sentences, no fragments or run-ons (L.4.1)"]},{alt:{group:"write",key:"story",label:"Story",icon:"📖",hint:"Tell a real or made-up story"},std:["W.4.3","L.4.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">Write a story about a job that was too big for one person. It can be real or made up. Write 5 or 6 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Start by telling who is in the story and where they are</li><li>Tell what happens in order. Use words like first, later, finally</li><li>Add details: what people said, saw, or felt</li><li>Give your story an ending</li></ul>`,key:["Sets up the situation and introduces a narrator or characters (W.4.3)","Events unfold in a clear order, with transition words like first, later, finally (W.4.3)","Uses dialogue or description with concrete or sensory details (W.4.3)","Ends with a conclusion that follows from the events (W.4.3)","Complete sentences, no fragments or run-ons (L.4.1)"]}]},{id:17,title:"Built to Survive",short:"Structures",parts:[{std:["4-LS1-1"],n:3,dur:75,dir:"Look at the two living things. Answer out loud or in writing.",desc:"arguing that named plant and animal structures do a job that supports survival or growth",html:()=>`<p class="big">A palm leans over the beach where the map says to dig. A land crab lives in a burrow under it.</p>
     <div class="figure">${F.icon("palm",104)}${F.icon("crab",104)}</div>
     <p class="big">A structure is a part of a living thing. Some structures are on the outside, where you can see them. Some are on the inside.</p>`,qs:["Name one outside structure of the palm and say what job it does for the tree.","The crab has a hard shell on the outside and gills on the inside. Pick one and say what job it does.","The palm's roots spread wide and shallow in loose sand. Build an argument that this helps the palm survive on a windy beach."],key:["Any real palm structure with a matching job: roots take in water and hold the tree down, the trunk holds the leaves up high, the leaves catch sunlight to make food, the fruit carries seeds to new places. A part named with no job attached is only half of this standard. (4-LS1-1)","The shell covers and protects the soft body and keeps it from drying out. The gills take oxygen out of the water. Either one, with the job stated. (4-LS1-1)","Wide shallow roots grip a large area of loose sand, so wind pushing the trunk is spread over many roots instead of one. Listen for a claim about survival plus a reason drawn from the wide shape, not just the word roots. (4-LS1-1)"]},{std:["4-LS1-2"],n:3,dur:75,dir:"Read what happens, then answer. You may draw your model.",desc:"modelling the path from sense organ to brain to response in an animal",html:()=>`<p class="big">A parrot sits on a low branch eating fruit. A coconut drops onto the sand behind it. The parrot flies up to a higher branch and then goes back to eating.</p>
     <div class="figure">${F.icon("parrot",104)}${F.icon("palm",104)}</div>`,qs:["Which sense took in the information, and which body part took it in?","What did the parrot's brain do between taking in the sound and moving its wings?","Draw or tell a model of the whole path. It starts with the coconut hitting the sand. It ends with the parrot landing on the higher branch. Use three steps."],key:["Hearing, taken in by the ears. Accept a student who says the parrot heard the thump. (4-LS1-2)","The brain processed the information: it worked out what the sound meant and chose a response. Look for the idea that the brain decided, not that the ears made the wings move. (4-LS1-2)","Three steps in order: the ears take in the sound, the brain processes it and chooses what to do, the wings carry out the response. A model with only two steps is missing the brain and is approaching, not proficient. (4-LS1-2)"]}]},{id:18,title:"Layers in the Sea Cliff",short:"Rock Layers",parts:[{std:["4-ESS1-1"],n:3,dur:90,dir:"Study the cliff. Answer out loud or in writing.",desc:"reading rock layers and the fossils in them as evidence of landscape change",html:()=>`<p class="big">The crew digs into a cliff beside the beach. The layers are stacked like pages, newest on top.</p>
     <table class="bigTable"><tr><th>Layer</th><th>What the rock is like</th><th>Fossils found in it</th></tr>
     <tr><td>top</td><td>loose sand</td><td>none</td></tr>
     <tr><td>second</td><td>sandstone</td><td>sand dollars</td></tr>
     <tr><td>third</td><td>hard grey mud rock</td><td>small fish</td></tr>
     <tr><td>bottom</td><td>dark mud rock</td><td>fern leaves</td></tr></table>`,qs:["Which layer formed first? Point to the evidence in the chart.","Two layers hold fossils of things that lived in the ocean. What does that tell you about this spot long ago?","Use the layers in order to tell the story of how this place changed over time."],key:["The bottom layer. Layers pile up from the bottom, so the lowest one was already there before the others landed on it. (4-ESS1-1)","This spot was under sea water during the time those two layers formed. Sand dollars and fish live in the ocean, so the water must have been here. (4-ESS1-1)","Ferns grew on land, then the sea covered the spot while fish and then sand dollars lived there, then the water left and loose sand blew over the top. Any order that follows the chart from the bottom up and names a change from land to water and back counts. (4-ESS1-1)"]},{std:["4-ESS2-1"],n:3,dur:75,dir:"Look at the measurements. Answer out loud or in writing.",desc:"using measurements to compare how fast water, wind and plant roots change the land",html:()=>`<p class="big">The crew built four trays of the same sand, each one 30 centimetres long. They treated each tray for ten minutes and then weighed the sand that washed or blew off the end.</p>
     <table class="bigTable"><tr><th>Tray</th><th>What was done to it</th><th>Sand lost</th></tr>
     <tr><td>1</td><td>water poured slowly</td><td>12 grams</td></tr>
     <tr><td>2</td><td>water poured fast</td><td>41 grams</td></tr>
     <tr><td>3</td><td>air blown across with a fan</td><td>7 grams</td></tr>
     <tr><td>4</td><td>water poured fast over sand planted with grass</td><td>9 grams</td></tr></table>`,qs:["Which tray lost the most sand? What did the water do to that sand?","Compare tray 2 and tray 4. What did the grass do to the rate of erosion?","Which numbers in the chart are the evidence that pouring water faster wears away more sand? Say the numbers."],key:["Tray 2, 41 grams. The fast water carried the loose grains away and moved them off the end of the tray. (4-ESS2-1)","The grass slowed it down a lot: 41 grams without grass and only 9 grams with it. Roots hold the grains in place so moving water cannot pick them up as easily. (4-ESS2-1)","12 grams for slow water and 41 grams for fast water, the same sand and the same ten minutes. Both numbers are needed. One number alone is not a comparison. (4-ESS2-1)"]}]},{id:19,title:"Reading the Map",short:"Map Patterns",parts:[{std:["4-ESS2-2"],n:3,dur:90,dir:"Study the chart of the islands. Answer out loud or in writing.",desc:"interpreting map data to describe a pattern in Earth's features",html:()=>`<p class="big">Eight islands sit in a line from south to north. The chart gives what the map shows at each one.</p>
     <div class="figure">${F.icon("island",88)}${F.icon("volcano",88)}${F.icon("mountain",88)}</div>
     <table class="bigTable"><tr><th>Island</th><th>Tallest point</th><th>Cone shaped peak?</th></tr>
     <tr><td>1 south end</td><td>40 m</td><td>no</td></tr>
     <tr><td>2</td><td>120 m</td><td>no</td></tr>
     <tr><td>3</td><td>610 m</td><td>yes</td></tr>
     <tr><td>4</td><td>980 m</td><td>yes</td></tr>
     <tr><td>5</td><td>1,240 m</td><td>yes</td></tr>
     <tr><td>6</td><td>1,010 m</td><td>yes</td></tr>
     <tr><td>7</td><td>330 m</td><td>no</td></tr>
     <tr><td>8 north end</td><td>60 m</td><td>no</td></tr></table>`,qs:["Describe the pattern in the heights as you read from island 1 to island 8.","Where on the chain are the cone shaped peaks? Say it as a pattern, not as a list.","A ninth island is found between islands 4 and 5. Use the pattern to say what its map is likely to show."],key:["The heights rise from the south end to the middle and then fall again toward the north end. Island 5 is the tallest at 1,240 metres. (4-ESS2-2)","They are all grouped in the middle of the chain, islands 3 to 6, which are also the tall ones. A student who only reads the list back is approaching. (4-ESS2-2)","A tall point, somewhere near 1,000 to 1,200 metres, and a cone shaped peak, because it sits in the middle group where both of those appear. The prediction has to be tied to the pattern. (4-ESS2-2)"]},{std:["4-ESS3-2"],n:3,dur:95,dir:"Read the two plans. Answer out loud or in writing.",desc:"generating and comparing solutions that reduce the impact of a natural Earth process",html:()=>`<p class="big">Twice a year the stream behind the camp rises and spreads mud across the garden. The crew has two plans and enough time and material for one.</p>
     <table class="bigTable"><tr><th>Plan</th><th>What it does</th><th>Cost</th><th>How long it lasts</th></tr>
     <tr><td>A: stone wall</td><td>holds the water in the channel</td><td>high</td><td>many years</td></tr>
     <tr><td>B: plant willows along the bank</td><td>roots hold the bank and soak up water</td><td>low</td><td>better each year as they grow</td></tr></table>`,qs:["Give one more idea of your own that would reduce the mud in the garden.","Compare plan A and plan B. Which would you choose. What does the chart say that backs your choice?","Now you have three plans: plan A, plan B and your own. Put all three in order, most useful to least useful for this garden. Then say what you ordered them on."],key:["Any workable idea: dig a channel that carries the water past the garden, move the garden to higher ground, build raised beds, lay a bank of sandbags before the wet season, spread gravel. It has to reduce the effect of the rising water, not stop the rain. (4-ESS3-2)","Either plan, judged on the chart. Plan A works the first season and costs the most. Plan B costs little and keeps improving but is weak in its first year. The choice itself is not what is rated: the reason pulled from the chart is. (4-ESS3-2)","Any order, rated on the measure the student orders by and on whether the same measure is applied to all three plans. Cost, how soon it starts working, how long it lasts and how much of the mud it keeps off the garden are all fair measures, and the chart supplies the first three for A and B. Or: a student who orders on two measures at once and says which one decided it is reasoning well. Partial: an order given with no measure named, or a measure applied to only one of the three, is approaching. (4-ESS3-2)"]}]},{id:20,title:"Fuel for the Voyage",short:"Energy Sources",parts:[{std:["4-ESS3-1"],n:3,dur:90,dir:"Study the chart. Answer out loud or in writing.",desc:"describing where energy and fuels come from and how using them affects the environment",html:()=>`<p class="big">The crew keeps a chart of everything that gives them energy on the island.</p>
     <table class="bigTable"><tr><th>Source</th><th>Where it comes from</th><th>Can it run out?</th><th>One effect of using it</th></tr>
     <tr><td>ship's diesel</td><td>oil pumped from under the ground</td><td>yes</td><td>smoke into the air</td></tr>
     <tr><td>firewood</td><td>trees on the island</td><td>yes, if cut faster than it grows</td><td>fewer trees, smoke</td></tr>
     <tr><td>wind pump</td><td>moving air</td><td>no</td><td>takes space, noisy</td></tr>
     <tr><td>sun panel</td><td>sunlight</td><td>no</td><td>takes space, has to be made and shipped</td></tr></table>`,qs:["Pick two sources from the chart and say which natural resource each one is made from.","Which two sources will not run out? What is it about them that keeps them coming?","The crew burns less diesel and uses the wind pump more. Name one effect on the environment that gets smaller and one new effect that appears."],key:["Any two read correctly: diesel from oil under the ground, firewood from trees, the wind pump from moving air, the sun panel from sunlight. (4-ESS3-1)","The wind pump and the sun panel. The wind keeps blowing and the sun keeps shining, so the supply is renewed instead of used up. (4-ESS3-1)","Less smoke going into the air. The new effect is from the chart: the pump takes up space and makes noise, and panels have to be made and shipped. Naming only the good half is approaching. (4-ESS3-1)"]}]},{id:21,title:"Speed and Crashes",short:"Speed",parts:[{std:["4-PS3-1"],n:3,dur:75,dir:"Look at the results. Answer out loud or in writing.",desc:"using evidence to explain how the speed of an object relates to its energy",html:()=>`<p class="big">The crew rolled the same loaded cart down a plank three times and let it hit a wooden block at the bottom. They measured how fast the cart was going and how far it pushed the block.</p>
     <table class="bigTable"><tr><th>Try</th><th>Speed of the cart</th><th>How far the block slid</th></tr>
     <tr><td>1</td><td>slow</td><td>4 cm</td></tr>
     <tr><td>2</td><td>medium</td><td>11 cm</td></tr>
     <tr><td>3</td><td>fast</td><td>26 cm</td></tr></table>`,qs:["What happens to the distance the block slides as the cart's speed goes up?","Which try had the most energy in the moving cart? Use the measurements as your evidence.","Explain, using the chart, how the speed of an object is related to its energy."],key:["It goes up: 4 cm, then 11 cm, then 26 cm. (4-PS3-1)","Try 3, the fast one. It pushed the block 26 cm, farther than the other two, so it had more energy to give the block. (4-PS3-1)","The faster an object moves, the more energy it has. The evidence is that each faster cart moved the same block farther. Look for both the claim and at least one number. (4-PS3-1)"]},{std:["4-PS3-3"],n:3,dur:75,dir:"Answer out loud or in writing. You do not need the real answer for your prediction, just a reason.",desc:"asking a question and predicting the energy change in a collision",html:()=>`<p class="big">Two carts of the same size sit on a flat deck. One is loaded with stones. The crew will roll the loaded cart into the empty one, which is standing still.</p>
     <div class="figure">${F.icon("box",96)}${F.icon("box",96)}</div>`,qs:["Ask one question about this collision that a test could answer.","Predict what happens to the empty cart. What happens to the loaded cart's speed.","Where does the energy go when the two carts hit? Name two places."],key:["Any testable question: how far will the empty cart go, will it go faster if the loaded cart starts higher up, what happens if both carts are loaded, does the sound get louder with a faster crash. A question that cannot be tested, such as which cart is nicer, does not count. (4-PS3-3)","The empty cart is pushed and moves away. The loaded cart slows down. Either half is credit toward this; both halves is the full prediction. (4-PS3-3)","Any two of: into motion of the empty cart, into sound, into heating where they rub and hit, into shaking or bending the carts. Energy moving from one cart to the other is the main idea. (4-PS3-3)"]}]},{id:22,title:"Energy on the Move",short:"Transfer",parts:[{std:["4-PS3-2"],n:4,dur:75,dir:"For each observation, say how the energy travelled. Answer out loud or in writing.",desc:"matching observations to energy transferred by sound, light, heat or electric current",html:()=>`<p class="big">Four things the crew noticed in one evening.</p>
     <table class="bigTable"><tr><th></th><th>What they noticed</th></tr>
     <tr><td>1</td><td>The cook hits a metal pan and everyone across the beach looks up.</td></tr>
     <tr><td>2</td><td>A lamp is lit in the cabin and the far wall becomes bright.</td></tr>
     <tr><td>3</td><td>A metal spoon left in the soup pot becomes too hot to hold.</td></tr>
     <tr><td>4</td><td>A wire runs from the battery to the small bulb, and the bulb glows.</td></tr></table>`,qs:["How did the energy travel in observation 1?","How did it travel in observation 2?","How did it travel in observation 3?","How did it travel in observation 4?"],key:["By sound, through the air from the pan to everyone's ears. (4-PS3-2)","By light, from the lamp across the room to the wall. (4-PS3-2)","By heat, from the hot soup along the metal of the spoon to the handle. (4-PS3-2)","By an electric current, through the wire from the battery to the bulb. The bulb then gives out light and heat. (4-PS3-2)"]},{std:["4-PS3-4"],n:3,dur:90,dir:"Draw your device and label it. Then answer out loud or in writing.",desc:"designing, testing and improving a device that converts energy from one form to another",html:()=>`<p class="big">The crew needs a light at the cabin door that works without matches. Design a device that turns one kind of energy into light. You may use a small hand crank, a battery, wire, a bulb, a mirror, or a panel that takes in sunlight.</p>
     <div class="figure">${F.icon("lamp",96)}${F.icon("sun",96)}</div>`,qs:["Draw and label your device. Show where the energy goes in and where the light comes out.","Name the kind of energy going in and the kind coming out.","You test it and the bulb is too dim. Name one change you would make, and say why that change should help."],key:["Any labelled drawing with a path through it: a crank turning, wire, and a bulb; or sunlight, a panel, wire, and a bulb. Labels are what make it a design rather than a picture. (4-PS3-4)","Going in: motion from the crank, or light from the sun. Coming out: light, and heat as well. Naming both forms is the heart of this standard. (4-PS3-4)","Any change tied to a reason: crank faster to put in more energy, use a fresh battery, shorten the wire, tilt the panel toward the sun, add a mirror behind the bulb to send light forward. A change with no reason is approaching. (4-PS3-4)"]}]},{id:23,title:"Waves, Light and Signals",short:"Waves",parts:[{std:["4-PS4-1"],n:3,dur:75,dir:"Look at the two waves. Answer out loud or in writing.",desc:"using a wave model to describe amplitude and wavelength and the effect on a floating object",html:()=>`<p class="big">The crew drew the water at the shore on a calm day and on a windy day. The dotted line is the flat water level.</p>
     <div class="figure"><svg viewBox="0 0 520 300" width="520" role="img" aria-label="Two waves drawn above one another with letters A and B marking parts of the first wave">
       <text x="10" y="18" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">calm day</text>
       <line x1="20" y1="70" x2="500" y2="70" stroke="var(--line)" stroke-width="2" stroke-dasharray="6 6"/>
       <path d="M20 70 q30 -35 60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0" fill="none" stroke="var(--sea)" stroke-width="5"/>
       <line x1="50" y1="70" x2="50" y2="52" stroke="var(--coral)" stroke-width="4"/>
       <text x="62" y="60" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">A</text>
       <line x1="20" y1="112" x2="140" y2="112" stroke="var(--coral)" stroke-width="4"/>
       <text x="80" y="134" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif" text-anchor="middle">B</text>
       <text x="10" y="186" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">windy day</text>
       <line x1="20" y1="240" x2="500" y2="240" stroke="var(--line)" stroke-width="2" stroke-dasharray="6 6"/>
       <path d="M20 240 q30 -85 60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0" fill="none" stroke="var(--sea)" stroke-width="5"/>
     </svg></div>`,qs:["Which letter marks the amplitude of the calm day wave. Which marks the wavelength?","Compare the two drawings. Which measurement changed on the windy day, and did it get bigger or smaller?","A float bobs on the water. What does the wind day do to the way the float moves?"],key:["A marks the amplitude, the height from the flat line up to the top. B marks the wavelength, the distance from one wave to the next one like it. (4-PS4-1)","The amplitude got bigger. The waves are taller on the windy day. The wavelength is the same in both drawings, which is worth asking about if the student does not notice. (4-PS4-1)","The float rises and falls farther, because a wave with a bigger amplitude carries more energy and moves the float more. It still bobs up and down in place rather than travelling along with the wave. (4-PS4-1)"]},{std:["4-PS4-2"],n:3,dur:75,dir:"Answer out loud or in writing. You may draw arrows.",desc:"modelling how light reflects from an object into the eye so the object can be seen",html:()=>`<p class="big">A gold coin sits on the table in the cabin. The lamp is lit and the crew can see the coin. Then the lamp is covered and the room is completely dark.</p>
     <div class="figure">${F.icon("coin",96)}${F.icon("lamp",96)}</div>`,qs:["Draw or tell the path the light takes when the crew sees the coin. Name every place it goes.","In the completely dark room the coin is still on the table. Why can nobody see it?","Does the coin make its own light? How do you know from the two situations?"],key:["Light leaves the lamp, travels to the coin, reflects off the coin, and travels into the eye. All three legs are needed: lamp to coin, coin to eye, and the eye taking it in. (4-PS4-2)","There is no light to reflect off the coin, so no light reaches the eye. Seeing needs light coming into the eye, not just an object being there. (4-PS4-2)","No. In the dark room it cannot be seen at all, so the light must have been coming from the lamp and bouncing off it. A thing that made its own light would still show in the dark. (4-PS4-2)"]},{std:["4-PS4-3"],n:3,dur:75,dir:"Read the two codes. Answer out loud or in writing.",desc:"comparing two solutions that use patterns to send information",html:()=>`<p class="big">The camp and the ship need to send three messages across the water at night: all is well, send the boat, and we are moving camp.</p>
     <table class="bigTable"><tr><th>Code</th><th>How a message is sent</th><th>Needs</th></tr>
     <tr><td>Lantern flashes</td><td>one long flash, two short flashes, or three short flashes</td><td>a lantern, works in fog if close</td></tr>
     <tr><td>Flag shapes</td><td>a square flag, a round flag, or a striped flag raised on the pole</td><td>daylight, a clear view</td></tr></table>`,qs:["How does a pattern carry the information in each code? Say it for both.","Which code works better for a message sent at night? Give your reason from the chart.","Design a third pattern of your own for the same three messages, using something other than light or flags."],key:["In the flash code the pattern is the number and length of the flashes. In the flag code the pattern is which shape is flying. Either way an agreed pattern stands for a message, which is how information is transferred. (4-PS4-3)","The lantern flashes, because flags need daylight and a clear view while a lantern can be seen in the dark. (4-PS4-3)","Any pattern with agreed meanings: a count of bell rings, a long and short horn blast, knocks on a hull, a pattern of drum beats, three different whistle notes. It has to have at least three distinct signals, one for each message. (4-PS4-3)"]}]},{id:24,title:"Build It and Test It",short:"Design",parts:[{std:["3-5-ETS1-1"],n:3,dur:60,dir:"Read the situation, then answer out loud or in writing.",desc:"defining a design problem with criteria for success and constraints",html:()=>`<p class="big">The water jug on the deck tips over whenever the boat rocks. The crew loses the water. They have one afternoon, a box of rope, two planks, and no nails.</p>
     <div class="figure">${F.icon("drop",88)}${F.icon("anchor",88)}</div>`,qs:["State the problem in one sentence, in your own words.","Write two criteria: how will the crew know the fix worked?","Write two constraints from the situation."],key:["Something like: the jug needs to stay upright on a rocking deck so the water is not lost. A problem statement, not a solution. (3-5-ETS1-1)","Any two testable criteria: the jug stays upright when the deck tilts, no water spills, the crew can still lift the jug to pour, it holds through a whole trip. (3-5-ETS1-1)","One afternoon of time, only rope and two planks, no nails. Any two of those. A student who lists a criterion here instead has the two ideas mixed and is approaching. (3-5-ETS1-1)"]},{std:["3-5-ETS1-2"],n:3,dur:75,dir:"Study the three fixes. Answer out loud or in writing.",desc:"generating and comparing solutions against the criteria and constraints",html:()=>`<p class="big">Three fixes for the water jug.</p>
     <table class="bigTable"><tr><th>Fix</th><th>What it is</th><th>Materials needed</th><th>Time to build</th></tr>
     <tr><td>1</td><td>a rope lashing that ties the jug to the rail</td><td>rope</td><td>short</td></tr>
     <tr><td>2</td><td>a wooden cradle the jug sits down inside</td><td>two planks and nails</td><td>long</td></tr>
     <tr><td>3</td><td>a ring of rope coiled flat as a nest for the jug</td><td>rope</td><td>short</td></tr></table>`,qs:["Which fix breaks a constraint? Name the constraint it breaks.","Compare fix 1 and fix 3 against the criteria. Which is likely to hold the jug better?","Add a fourth idea of your own that fits the materials and the time."],key:["Fix 2. It needs nails and the crew has none, and it also takes longer than one afternoon of work allows. (3-5-ETS1-2)","Fix 1, the lashing, because tying the jug to the rail holds it when the deck tilts, while a flat coil only keeps it from sliding on a small tilt. A student who argues for fix 3 on the grounds that the crew can still lift the jug out easily is reasoning from the criteria too, so accept it with that reason. (3-5-ETS1-2)","Any idea using rope or planks in the time given: wedge the jug between two planks and lash the planks, hang the jug in a rope sling, lay the jug on its side in a rope nest and lash it. (3-5-ETS1-2)"]},{std:["3-5-ETS1-3"],n:3,dur:75,dir:"Answer out loud or in writing.",desc:"planning a fair test with controlled variables and naming a failure point",html:()=>`<p class="big">The crew wants to find out which fix holds the jug better, the rope lashing or the rope nest. They can tilt a plank to make the deck rock.</p>
     <div class="figure">${F.icon("board",96)}${F.icon("drop",96)}</div>`,qs:["Plan the test. What will you measure?","Name two things you must keep the same in both tries so the test is fair.","Name one failure point: a place where your fix is most likely to give way first."],key:["Any measured outcome: the tilt angle at which the jug falls, how many rocks it survives, how much water spills, counted or measured the same way for both. (3-5-ETS1-3)","Any two: the same jug with the same amount of water in it, the same plank tilted the same amount, the same number of rocks, the same speed of rocking, the same person doing the rocking. Changing only the fix is the whole point. (3-5-ETS1-3)","Any sensible weak spot: the knot could slip, the rope could stretch, the coil could slide across the deck, the rail could be too far away, the jug handle could break. The point is to name where to watch, not to be right. (3-5-ETS1-3)"]}]},{id:25,title:"Regions of California",short:"Regions",parts:[{std:["HSS-4.1"],n:4,dur:90,dir:"Study the chart of four regions. Answer out loud or in writing.",desc:"describing the physical and human geographic features that define California's regions",html:()=>`<p class="big">California is often described in four big regions. Here is what the map shows for each one.</p>
     <div class="figure">${F.icon("mountain",80)}${F.icon("wheat",80)}${F.icon("wave",80)}${F.icon("cactus",80)}</div>
     <table class="bigTable"><tr><th>Region</th><th>Land</th><th>Water</th><th>What people do there</th></tr>
     <tr><td>Coast</td><td>beaches, low hills, fog</td><td>the Pacific Ocean</td><td>ports, fishing, cities</td></tr>
     <tr><td>Central Valley</td><td>flat, deep soil</td><td>the Sacramento and San Joaquin rivers</td><td>farming, canals, the state capital</td></tr>
     <tr><td>Mountains</td><td>the Sierra Nevada, high peaks</td><td>deep snow, lakes, rivers that start here</td><td>timber, visitors, dams that store water</td></tr>
     <tr><td>Desert</td><td>dry basins, rock, Death Valley</td><td>very little rain</td><td>small towns, solar farms, long roads</td></tr></table>`,qs:["Which region is on the western edge of the state. What body of water forms that edge?","The Central Valley has deep soil but not much rain. The Sierra Nevada gets deep snow. Explain how those two facts fit together for farmers.","Name one physical feature and one human feature from the chart and say the difference between the two kinds.","Sacramento is the state capital. Which region is it in. Then name one reason a city would grow in that spot."],key:["The Coast region, on the Pacific Ocean. (HSS-4.1)","Snow in the mountains melts in spring and runs down the rivers into the valley, where canals and dams carry and store it for the fields. The valley's farms depend on water that falls somewhere else. Partial: naming the snowmelt with no account of how it reaches the fields is approaching. (HSS-4.1)","Physical features are made by nature: beaches, rivers, peaks, soil, fog, snow. Human features are made by people: ports, canals, dams, cities, roads, solar farms. Both named, with the difference stated. Partial: one of each named with no difference stated is approaching. (HSS-4.1)","The Central Valley. Any sound reason: two rivers meet near there, flat land, river boats could reach it, it sat between the gold country and the coast, farms and trade all around. Partial: the region right with no reason the city grew there is approaching. (HSS-4.1)"]}]},{id:26,title:"Before the Rush, and the Rush",short:"California Past",parts:[{std:["HSS-4.2"],n:3,dur:200,dir:"Read the chart, then answer out loud or in writing.",desc:"describing life and the interactions among peoples of California from the first peoples through the mission and rancho periods",html:()=>`<p class="big">Three periods in early California.</p>
     <table class="bigTable"><tr><th>Period</th><th>Who lived and worked there</th><th>How people got food and goods</th></tr>
     <tr><td>First peoples, for thousands of years</td><td>many separate nations, among them the Chumash on the south coast, the Yokuts in the valley, and the Miwok in the foothills</td><td>acorns ground into meal, fish and shellfish, deer, seeds and roots; trading shell beads along set routes</td></tr>
     <tr><td>Spanish mission period, from 1769</td><td>Spanish Franciscan missionaries, soldiers and settlers, and Native Californians who were brought to live and work at the missions</td><td>wheat and corn fields, cattle, workshops making tiles, leather and cloth; supplies carried along El Camino Real</td></tr>
     <tr><td>Mexican rancho period, from the 1820s</td><td>rancho families holding large land grants, and Native Californian workers who tended the herds</td><td>huge cattle herds; hides and tallow traded to ships from far away for cloth, tools and furniture</td></tr></table>
     <p class="big">Each California Indian nation had its own religious beliefs, its own account of how the world began, and its own ceremonies. They were not one shared religion. Chumash ceremonies were led by trained specialists, and one of them marked the turning of the sun in winter. Miwok nations danced in a large round earth covered ceremonial house after the acorn harvest. Yokuts nations held a mourning ceremony each year for the people who had died since the last one.</p>
     <p class="big">Spain sent the Franciscans, a Catholic religious order, to found the missions. Their purpose was to convert Native Californians to Christianity and to teach them Spanish farming, herding and trades. The missionaries and the soldiers directed the work and the daily routine, and Native Californian families lost the use of land their nations had held.</p>`,qs:["Name two foods the first peoples of California depended on. Then say where each came from. Then name one ceremony from the note and say which nation held it.","According to the note, what were the Franciscan missionaries sent to California to do? Then name one way life changed for Native Californians at the missions.","Ranchos traded hides and tallow to ships. What did California get back, and why would a rancho trade that way?"],key:["Any two foods with a source: acorns from oak trees, fish and shellfish from the ocean and rivers, deer hunted on land, seeds and roots gathered. Naming a food with no source is half. Ceremony, any one correctly matched: the Chumash ceremony marking the turning of the sun in winter, led by trained specialists; the Miwok dances in the round earth covered ceremonial house after the acorn harvest; the Yokuts yearly mourning ceremony. Credit as well a student who says the nations had separate beliefs rather than one religion. Partial: two foods with sources but no ceremony, or a ceremony with only one sourced food, is approaching. (HSS-4.2)","They were sent to convert Native Californians to Christianity and to teach them Spanish farming, herding and trades. For the change, accept any of these: people were brought to live and work at the missions, the missionaries and soldiers set the work and the daily routine instead of their own nations, they farmed wheat and raised cattle instead of gathering acorns, they worked in the workshops, or families lost the use of land their nations had held. Both halves are needed for full credit. Partial: one half without the other is approaching, so naming the purpose with no change at the missions sits there. (HSS-4.2)","Cloth, tools and furniture, things not made in California at the time. A rancho had far more cattle than it could use and no factories, so trading what it had in plenty for what it could not make was the way to get those goods. Partial: the goods named with no reason a rancho would trade that way is approaching. (HSS-4.2)"]},{std:["HSS-4.3"],n:3,dur:90,dir:"Study the timeline, then answer out loud or in writing.",desc:"explaining the events from the Bear Flag Republic through the Gold Rush to statehood",html:()=>`<p class="big">Four years that changed California.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1846</td><td>A group of American settlers at Sonoma raised a flag with a bear on it and declared the Bear Flag Republic. The war between the United States and Mexico reached California the same year.</td></tr>
     <tr><td>1848</td><td>Gold was found in the American River at Sutter's Mill in Coloma. The war ended and Mexico gave California to the United States.</td></tr>
     <tr><td>1849</td><td>About 80,000 people came looking for gold. They were called forty-niners. San Francisco grew from a village into a city in a single year.</td></tr>
     <tr><td>1850</td><td>California became the 31st state.</td></tr></table>`,qs:["What was the Bear Flag Republic. How long did California stay under that flag?","Gold was found in 1848 and 80,000 people arrived in 1849. Name two ways that many newcomers would change the places they went to.","Put these in order. Say what connects them. Statehood. The Gold Rush. The end of the war with Mexico."],key:["A short lived republic declared by American settlers at Sonoma in 1846. It lasted only weeks, because the war brought California under the United States that same year. Partial: naming the republic with no account of how long it lasted is approaching. (HSS-4.3)","Any two reasoned effects: towns appeared overnight and some emptied again, prices rose because goods were scarce, mining tore up riverbeds, Native Californian and Mexican Californian families were pushed off land they lived on, roads, stores and shipping grew to supply the miners, courts and laws were needed where there were none. Partial: one reasoned effect is approaching, and two effects asserted with no reasoning is approaching too. (HSS-4.3)","The war with Mexico ended in 1848, the Gold Rush came in 1848 and 1849, statehood came in 1850. The connection is that the gold brought so many people so fast that California had the population and the pressure to become a state within two years instead of waiting as a territory. Partial: the three in the right order with no connection named is approaching. (HSS-4.3)"]}]},{id:27,title:"Farms, Water and Who Decides",short:"Government",parts:[{std:["HSS-4.4"],n:3,dur:90,dir:"Study the chart, then answer out loud or in writing.",desc:"tracing how California became an agricultural and industrial power since the 1850s",html:()=>`<p class="big">Four changes that built the California economy after the Gold Rush.</p>
     <table class="bigTable"><tr><th>Change</th><th>What it did</th></tr>
     <tr><td>The transcontinental railroad, finished in 1869</td><td>joined California to the eastern states, so fruit and wheat could be sold far away and people could arrive by train</td></tr>
     <tr><td>Canals and aqueducts, from the 1870s on</td><td>carried water to dry land, turning valley floor into orchards and row crops</td></tr>
     <tr><td>Oil wells, from the 1890s</td><td>fuel for trains, ships, factories and later cars</td></tr>
     <tr><td>Factories and new industries, through the 1900s</td><td>aircraft, films, and later computers, drawing workers to cities</td></tr></table>`,qs:["How did the railroad change what a California farmer could grow and sell?","Why was moving water the change that mattered most for valley farming?","Pick one change from the chart and name one effect it had on where people lived or worked."],key:["Crops could be shipped to buyers thousands of miles away instead of only to nearby towns, so a farmer could plant much more than local people would eat and could grow crops worth shipping, such as fruit. Partial: saying the railroad helped with no account of the wider market is approaching. (HSS-4.4)","The valley has deep soil and long warm summers but little summer rain. Without canals and aqueducts the land could not be watered through the growing season, so bringing water is what made the soil usable. Partial: naming the dry summers with nothing said about the canals is approaching. (HSS-4.4)","Any supported effect: the railroad built up towns along its line, aqueducts let farm towns grow where there had been dry range, oil brought work to Los Angeles and Kern County, factories and studios pulled people from farms into cities. Partial: a change named with no effect on where people lived or worked is approaching. (HSS-4.4)"]},{std:["HSS-4.5"],n:3,dur:90,dir:"Study the chart, then answer out loud or in writing.",desc:"explaining the structures, functions and powers of local, state and federal government",html:()=>`<p class="big">Three levels of government, and the three branches at the state and federal levels.</p>
     <table class="bigTable"><tr><th>Level</th><th>Who leads it</th><th>One thing it decides</th></tr>
     <tr><td>Local: city or county</td><td>a mayor and city council, or a county board of supervisors</td><td>local roads, parks, libraries, the fire department</td></tr>
     <tr><td>State: California</td><td>a governor, a legislature of two houses, and state courts</td><td>schools, state highways, water projects, the state budget</td></tr>
     <tr><td>Federal: the United States</td><td>the President, Congress of two houses, and the federal courts</td><td>the armed forces, money, mail, treaties with other countries</td></tr></table>`,qs:["Name the three branches at the state level and say what each one does.","A pothole on your street needs fixing. Which level of government would handle it, and why that one?","Why would a country split its power into three branches instead of giving it all to one person?"],key:["The legislature makes the laws, the governor and the departments carry them out, the courts decide what the laws mean in a case. The names matter less than the three jobs. Partial: two of the three jobs described is approaching. (HSS-4.5)","Local government, the city or county, because local streets are their responsibility. Accept a student who says the state would handle it if the road were a state highway. Partial: the level right with no reason is approaching. (HSS-4.5)","So that no one part holds all the power. Each branch checks the others, which is the plan written into the U.S. Constitution. Any answer built on the idea of limiting power counts. Partial: saying three branches share the work with no account of limiting power is approaching. (HSS-4.5)"]}]}];const LEVELUPS={3:{id:"L3",lv:true,title:"Level Up: Quote It",std:["RL.5.1"],needs:["RL.4.1"],n:1,dir:"Read the exact words out loud.",html:()=>`<p class="passage sm">${FABLE}</p><p class="big">Read me the exact words from the story that show Leo changed his mind.</p>`,key:["Reads the exact line: “Maybe it wasn’t hopeless. It just wasn’t a two-person job.” (RL.5.1, quoting accurately)"]},7:{id:"L7",lv:true,title:"Level Up: Verb Tenses",std:["L.5.1"],needs:["L.4.1"],n:2,dir:"Say each sentence out loud the correct way.",html:()=>`<ol class="qlist"><li>By the time we got there, the bus ____. (leave)</li><li>Fix it: She opens the door and waved.</li></ol>`,key:["had left (L.5.1, perfect tense)","She opened the door and waved, or She opens the door and waves. (L.5.1, fixing a tense shift)"]},12:{id:"L12",lv:true,title:"Level Up: Fraction Area",std:["5.NF.B.4"],needs:["4.MD.A.3"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">A garden bed is 6 feet long and 3/4 of a foot wide. What is its area?</p>`,key:["4 1/2 square feet: 6 × 3/4 = 18/4. (5.NF.B.4, multiplying a whole number by a fraction to find the area of a rectangle with a fractional side length)"]},14:{id:"L14",lv:true,title:"Level Up: Add Fractions",std:["5.NF.A.1"],needs:["4.NF.A.1"],n:1,dir:"Solve on your paper and hold it up.",html:()=>`<p class="huge" style="font-size:clamp(3rem,10vw,6rem)">1/2 + 1/3</p>`,key:["5/6 (3/6 + 2/6) (5.NF.A.1)"]}};const PASSAGE_STD=["RL.4.1","RL.4.4","RI.4.1","RI.4.9","RL.5.1","W.4.8","W.4.2"];const MULT_N=12,FRAC_DENS=[1,2,3,4,5,6,8,10,12];let multSel=[0,0],pvVal="",pvStop=null,fracOn={},gridOn=[0,0];function pvCols(st){return st&&st.std&&st.std.some(x=>x.indexOf("4.NF.C")===0)?{ints:["Tens","Ones"],decs:["Tenths","Hundredths"]}:{ints:["Hundred<br>thousands","Ten<br>thousands","Thousands","Hundreds","Tens","Ones"],decs:[]}}const STARTERS={opinion:["I think ____ because ____.","One reason is ____.","For instance, ____.","In addition, ____.","That is why ____."],facts:["Earthworms help a garden by ____.","One fact is ____.","For example, ____.","Also, ____.","In conclusion, ____."],story:["One day, ____.","First, ____.","Later, ____.","Finally, ____.","In the end, ____."]};function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function pvTable(st){const cols=pvCols(st),raw=pvVal.replace(/[^0-9.]/g,""),bits=raw.split("."),ip=bits[0]||"",dp=bits[1]||"";let h="<tr>";cols.ints.forEach(c=>h+=`<th>${c}</th>`);if(cols.decs.length){h+=`<th class="pt"></th>`;cols.decs.forEach(c=>h+=`<th>${c}</th>`)}h+="</tr><tr>";cols.ints.forEach((c,i)=>{const k=ip.length-(cols.ints.length-i);h+=`<td>${k>=0?ip[k]:""}</td>`});if(cols.decs.length){h+=`<td class="pt">.</td>`;cols.decs.forEach((c,i)=>h+=`<td>${dp[i]||""}</td>`)}return h+"</tr>"}function pvHtml(st){pvStop=st;return`<label class="pv-in">Type a number<input type="text" inputmode="decimal" id="pvInput" value="${pvVal}" autocomplete="off"></label><div class="tool-scroll"><table class="pv" id="pvTable">${pvTable(st)}</table></div>`}function fracHtml(){return FRAC_DENS.map(d=>{const on=fracOn[d]||0;let r=`<div class="fs-row">`;for(let k=0;k<d;k++)r+=`<button class="fs-part${d>=10?" sm":""}${k<on?" on":""}" data-d="${d}" data-k="${k}">${d===1?"1 whole":"1/"+d}</button>`;return r+"</div>"}).join("")+`<p class="small">Click a piece to shade up to it. Click the last shaded piece to clear the row.</p>`}function gridHtml(){return`<div class="hg-wrap">`+[0,1].map(g=>{let c=`<div><div class="hg">`;for(let i=0;i<100;i++)c+=`<button class="hg-c${i<gridOn[g]?" on":""}" tabindex="-1" data-g="${g}" data-i="${i}" aria-label="Grid ${"AB"[g]} square ${i+1}"></button>`;return c+`</div><p class="fig-label" style="margin:4px 0 0">Grid ${"AB"[g]}</p></div>`}).join("")+`</div><p class="small">Each grid is 1 whole. Click a square to shade up to it. One full column is one tenth. Click the last shaded square to clear.</p>`}function measHtml(){const rows=[["Length",["1 meter = 100 centimeters","1 kilometer = 1,000 meters","1 foot = 12 inches","1 yard = 3 feet"]],["Weight and mass",["1 kilogram = 1,000 grams","1 pound = 16 ounces"]],["Liquid",["1 liter = 1,000 milliliters"]],["Time",["1 hour = 60 minutes","1 minute = 60 seconds"]]];return`<table class="meas">`+rows.map(r=>`<tr><th>${r[0]}</th></tr>`+r[1].map(x=>`<tr><td>${x}</td></tr>`).join("")).join("")+"</table>"}function formHtml(){return`<svg viewBox="0 0 320 170" width="320" role="img" aria-label="Rectangle with length and width labeled" style="display:block;margin:0 auto;max-width:100%;height:auto"><rect x="70" y="14" width="220" height="110" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="4"/><text x="180" y="154" text-anchor="middle" font-size="22" font-weight="700" fill="var(--ink)">length</text><text x="60" y="76" text-anchor="end" font-size="22" font-weight="700" fill="var(--ink)">width</text></svg>
  <p class="formula">Area = length × width</p><p class="small" style="margin-top:0">The space inside. Answer in square units.</p>
  <p class="formula">Perimeter = length + width + length + width</p><p class="small" style="margin-top:0">The distance around the outside.</p>`}const SENT_ALIAS={opinion:"W.4.1",facts:"W.4.2",story:"W.4.3","W.4.1":"opinion","W.4.2":"facts","W.4.3":"story"};function sentKey(st){const ps=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const pick=c=>!c?null:STARTERS[c]?c:SENT_ALIAS[c]&&STARTERS[SENT_ALIAS[c]]?SENT_ALIAS[c]:null;for(const p of ps){const a=pick(p.alt&&p.alt.key||p.wk||p.wt);if(a)return a;for(const c of p.std||[]){const k=pick(c);if(k)return k}}return null}function sentHtml(st){const k=sentKey(st);return`<ul class="starters">${(STARTERS[k]||STARTERS.opinion).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["4.OA.A.1","4.MD.A.1","4.MD.A.3","4.NF.A.1","4.NF.A.2","5.NF.B.4","5.NF.A.1"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const rr=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===rr&&multSel[1]===k?[0,0]:[rr,k];r()})},pv:{name:"Place value chart",std:["4.NBT.A.1","4.NBT.A.3","4.NF.C.6","4.NF.C.7"],html:pvHtml,bind:(b,r,st)=>{const inp=b.querySelector("#pvInput"),tb=b.querySelector("#pvTable");if(inp&&tb)inp.oninput=()=>{pvVal=inp.value.replace(/[^0-9.,]/g,"");tb.innerHTML=pvTable(st||pvStop)}}},frac:{name:"Fraction strips",std:["4.NF.A.1","4.NF.A.2","5.NF.A.1"],html:fracHtml,bind:(b,r)=>b.querySelectorAll(".fs-part").forEach(x=>x.onclick=()=>{const d=+x.dataset.d,k=+x.dataset.k;fracOn[d]=fracOn[d]===k+1?0:k+1;r()})},grid:{name:"Hundredths grids",std:["4.NF.C.6","4.NF.C.7"],html:gridHtml,bind:(b,r)=>b.querySelectorAll(".hg-c").forEach(x=>x.onclick=()=>{const g=+x.dataset.g,i=+x.dataset.i;gridOn[g]=gridOn[g]===i+1?0:i+1;r()})},meas:{name:"Measurement chart",std:["4.MD.A.1"],html:measHtml},form:{name:"Area and perimeter card",std:["4.MD.A.3"],html:formHtml},sent:{name:"Sentence starters",std:["W.4.1","W.4.2","W.4.3"],html:sentHtml}};const SUP_CAVEATS=[{t:"pv",std:["4.NBT.A.1"],msg:"The place value chart names the places, so the student does not have to recall place names. The ten times comparisons still need the student’s own reasoning."},{t:"frac",msg:"Fraction strips can show the answer. Rate on whether the student can explain what the strips show."},{t:"meas",msg:"4.MD.A.1 expects students to know the unit sizes. With the measurement chart, this stop shows converting only."},{t:"form",msg:"With the area and perimeter card, this stop shows the student can use the formulas, not that they remember them."},{t:"sent",msg:"Sentence starters supply the linking words and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
